$contains = function ( $source, $contract ) {
	$tokens  = preg_split( '/\s+/', trim( $contract ) );
	$pattern = implode( '\\s+', array_map( function ( $token ) { return preg_quote( $token, '/' ); }, $tokens ) );
	return 1 === preg_match( '/' . $pattern . '/s', $source );
};
