$assert( false !== strpos( $admin, 'array_merge( $existing' ), 'Partial tab saves must merge with existing settings.' );
$assert( false !== strpos( $admin_view, "\$popup_css_key = \$popup_prefix . '_custom_css'" ) && false !== strpos( $admin_view, "\$shortcode_key = \$shortcode_prefix . '_shortcode_custom_css'" ), 'Popup and shortcode CSS fields must be mapped independently.' );
