$assert( false !== strpos( $admin_view, '后续设计' ) && false !== strpos( $admin_view, '后续接入群发系统' ), 'Lottery and bulk marketing placeholders missing.' );
$assert( false !== strpos( $public, "\$popup_settings['inquiry_custom_css']" ) && false !== strpos( $public, "\$popup_settings['subscribe_custom_css']" ) && false !== strpos( $public, "\$popup_settings['inquiry_shortcode_custom_css']" ) && false !== strpos( $public, "\$popup_settings['subscribe_shortcode_custom_css']" ), 'Four independent frontend CSS injections missing.' );
