$assert( false !== strpos( $admin_view, '$settings[ $shortcode_key ]' ) && false === strpos( $admin, $forbidden_combined_css ), 'Shortcode preview must apply only the current saved tab CSS.' );
$assert( false !== strpos( $admin_view, 'render_inline_shortcode()' ) && false !== strpos( $admin_view, '->render();' ), 'Shortcode preview must use canonical renderer implementations.' );
$assert( false !== strpos( $popup, "subscribe_shortcode_show_title' => 0" ) && false !== strpos( $popup, "subscribe_shortcode_show_subtitle' => 0" ) && false !== strpos( $popup, "subscribe_shortcode_show_image' => 0" ), 'Subscribe shortcode display defaults must be off.' );
$assert( false !== strpos( $admin_view, 'type="hidden"' ) && false !== strpos( $admin_view, '显示 Title' ) && false !== strpos( $admin_view, '显示 Subtitle' ) && false !== strpos( $admin_view, '显示 Image' ), 'Subscribe shortcode must expose independent checkbox controls with hidden off values.' );
$assert( false !== strpos( $subscribe, 'placeholder="EMAIL ADDRESS"' ) && false !== strpos( $subscribe, 'aria-label="EMAIL ADDRESS"' ) && false !== strpos( $subscribe, 'data-yby-subscribe-status aria-live="polite"></p>' ), 'Subscribe shortcode must render compact accessible markup with an empty status.' );
$assert( false !== strpos( $subscribe, "'image' => \$settings['subscribe_image']" ), 'Subscribe image toggle must use the existing subscribe_image setting.' );
$assert( false === strpos( $subscribe, 'Subscribe submission is not configured yet.' ) && false === strpos( $subscribe, '<label>Email' ), 'Compact subscribe defaults must omit provider text and email label.' );
